#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
sort(a.begin(),a.end());
long long cur=1;
for(int i=1;i<n;++i){if(a[i]>cur)cur=cur+1;}
printf("%lld\n",cur);return 0;}

